#include "road_network.hpp"
#include <cstdio>
#include <fstream>
#include <iterator>
uint32_t u32(const uint8_t *p){return uint32_t(p[0])|uint32_t(p[1])<<8|uint32_t(p[2])<<16|uint32_t(p[3])<<24;}
int main(int argc,char**argv){if(argc!=2)return 2;std::ifstream f(argv[1],std::ios::binary);std::vector<uint8_t>b((std::istreambuf_iterator<char>(f)),{});RoadNetwork net;std::string error;if(!readRoadNetwork(b,net,error))return 3;size_t cursor=20;for(int group=0;group<4;group++){size_t count=0,segments=0;uint32_t h=2166136261u;auto mix=[&](uint32_t v){std::printf("%08x ",v);h=(h^v)*16777619u;};auto seg=[&](const RoadSegment&s){for(auto w:s.words)mix(w);mix(s.flag);};if(group<2){count=net.nodes[group].size();for(auto&n:net.nodes[group]){cursor+=24+n.links.size()*5+n.lanes.size()*69;segments+=n.lanes.size();for(auto&lane:n.lanes){for(int i=0;i<4;i++)mix(lane.header[i]);mix(u32(lane.header.data()+4));mix(u32(lane.header.data()+8));seg(lane.segment);}}}else if(group==2){count=net.paths.size();for(auto&p:net.paths){cursor+=44+p.segments.size()*57;for(auto x:p.refs)mix(x);for(auto x:p.words)mix(x);segments+=p.segments.size();for(auto&s:p.segments)seg(s);}}else{count=net.others.size();for(auto&o:net.others){cursor+=89+o.segments.size()*57;for(auto x:o.refs)mix(x);mix(o.flag);for(auto x:o.words)mix(x);for(auto x:o.extraRefs)mix(x);for(auto x:o.tail)mix(x);segments+=o.segments.size();for(auto&s:o.segments)seg(s);}}std::printf("group=%d records=%zu segments=%zu cursor=%zu hash=%08x\n",group,count,segments,cursor,h);}}
